import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

public class Main {
    static int oxirgi(String ip) {
        return Integer.parseInt(ip.substring(ip.lastIndexOf('.') + 1));
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String boshi = in.next();
        String oxiri = in.next();
        String tarmoq = boshi.substring(0, boshi.lastIndexOf('.') + 1);
        Set<Integer> band = new HashSet<>();
        int n = in.nextInt();
        for (int i = 0; i < n; i++) band.add(oxirgi(in.next()));
        n = in.nextInt();
        for (int i = 0; i < n; i++) band.add(oxirgi(in.next()));
        List<Integer> keyin = new ArrayList<>();
        for (int o = oxirgi(boshi); o <= oxirgi(oxiri); o++) {
            if (!band.contains(o)) keyin.add(o);
        }
        int q = in.nextInt();
        for (int i = 0; i < q; i++) {
            if (i < keyin.size()) System.out.println(tarmoq + keyin.get(i));
            else System.out.println("NONE");
        }
    }
}

