#include <iostream>
#include <set>
#include <string>
#include <vector>
using namespace std;

int oxirgi(const string& ip) {
    return stoi(ip.substr(ip.rfind('.') + 1));
}

int main() {
    string boshi, oxiri;
    int n, q;
    cin >> boshi >> oxiri;
    string tarmoq = boshi.substr(0, boshi.rfind('.') + 1);
    set<int> band;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string ip;
        cin >> ip;
        band.insert(oxirgi(ip));
    }
    cin >> n;
    for (int i = 0; i < n; i++) {
        string ip;
        cin >> ip;
        band.insert(oxirgi(ip));
    }
    vector<int> keyin;
    for (int o = oxirgi(boshi); o <= oxirgi(oxiri); o++) {
        if (!band.count(o)) keyin.push_back(o);
    }
    cin >> q;
    for (int i = 0; i < q; i++) {
        if (i < (int)keyin.size()) cout << tarmoq << keyin[i] << endl;
        else cout << "NONE" << endl;
    }
    return 0;
}
